import { v, query } from "platform/functions";
import { booking } from "platform/entities";

export const busySlots = query({
  from: v.datetime(),
  to: v.datetime(),
}, async ({ from, to }) => {
  const start = new Date(from).getTime();
  const end = new Date(to).getTime();
  if (!Number.isFinite(start) || !Number.isFinite(end)) {
    return { slots: [] };
  }
  if (end <= start) {
    return { slots: [] };
  }
  const rows = await booking.find({
    starts_at: { $gte: new Date(from), $lt: new Date(to) },
    status: { $ne: "cancelled" },
  });
  return {
    slots: (rows ?? []).map((r) => ({
      starts_at: r.starts_at,
      ends_at: r.ends_at,
      seat: r.seat ?? null,
    })),
  };
});
